func testImpressoraToManyRemoveOpPrintProdutoGrupos(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Impressora
	var b, c, d, e ProdutoGrupo

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, impressoraDBTypes, false, strmangle.SetComplement(impressoraPrimaryKeyColumns, impressoraColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*ProdutoGrupo{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, produtoGrupoDBTypes, false, strmangle.SetComplement(produtoGrupoPrimaryKeyColumns, produtoGrupoColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	err = a.AddPrintProdutoGrupos(ctx, tx, true, foreigners...)
	if err != nil {
		t.Fatal(err)
	}

	count, err := a.PrintProdutoGrupos().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 4 {
		t.Error("count was wrong:", count)
	}

	err = a.RemovePrintProdutoGrupos(ctx, tx, foreigners[:2]...)
	if err != nil {
		t.Fatal(err)
	}

	count, err = a.PrintProdutoGrupos().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Error("count was wrong:", count)
	}

	if !queries.IsValuerNil(b.PrintID) {
		t.Error("want b's foreign key value to be nil")
	}
	if !queries.IsValuerNil(c.PrintID) {
		t.Error("want c's foreign key value to be nil")
	}

	if b.R.Print != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if c.R.Print != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if d.R.Print != &a {
		t.Error("relationship to a should have been preserved")
	}
	if e.R.Print != &a {
		t.Error("relationship to a should have been preserved")
	}

	if len(a.R.PrintProdutoGrupos) != 2 {
		t.Error("should have preserved two relationships")
	}

	// Removal doesn't do a stable deletion for performance so we have to flip the order
	if a.R.PrintProdutoGrupos[1] != &d {
		t.Error("relationship to d should have been preserved")
	}
	if a.R.PrintProdutoGrupos[0] != &e {
		t.Error("relationship to e should have been preserved")
	}
}

