func testImpressorasUpdate(t *testing.T) {
	t.Parallel()

	if 0 == len(impressoraPrimaryKeyColumns) {
		t.Skip("Skipping table with no primary key columns")
	}
	if len(impressoraAllColumns) == len(impressoraPrimaryKeyColumns) {
		t.Skip("Skipping table with only primary key columns")
	}

	seed := randomize.NewSeed()
	var err error
	o := &Impressora{}
	if err = randomize.Struct(seed, o, impressoraDBTypes, true, impressoraColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize Impressora struct: %s", err)
	}

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()
	if err = o.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Error(err)
	}

	count, err := Impressoras().Count(ctx, tx)
	if err != nil {
		t.Error(err)
	}

	if count != 1 {
		t.Error("want one record, got:", count)
	}

	if err = randomize.Struct(seed, o, impressoraDBTypes, true, impressoraPrimaryKeyColumns...); err != nil {
		t.Errorf("Unable to randomize Impressora struct: %s", err)
	}

	if rowsAff, err := o.Update(ctx, tx, boil.Infer()); err != nil {
		t.Error(err)
	} else if rowsAff != 1 {
		t.Error("should only affect one row but affected", rowsAff)
	}
}

func testImpressorasSliceUpdateAll(t *testing.T) {
	t.Parallel()

	if len(impressoraAllColumns) == len(impressoraPrimaryKeyColumns) {
		t.Skip("Skipping table with only primary key columns")
	}

	seed := randomize.NewSeed()
	var err error
	o := &Impressora{}
	if err = randomize.Struct(seed, o, impressoraDBTypes, true, impressoraColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize Impressora struct: %s", err)
	}

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()
	if err = o.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Error(err)
	}

	count, err := Impressoras().Count(ctx, tx)
	if err != nil {
		t.Error(err)
	}

	if count != 1 {
		t.Error("want one record, got:", count)
	}

	if err = randomize.Struct(seed, o, impressoraDBTypes, true, impressoraPrimaryKeyColumns...); err != nil {
		t.Errorf("Unable to randomize Impressora struct: %s", err)
	}

	// Remove Primary keys and unique columns from what we plan to update
	var fields []string
	if strmangle.StringSliceMatch(impressoraAllColumns, impressoraPrimaryKeyColumns) {
		fields = impressoraAllColumns
	} else {
		fields = strmangle.SetComplement(
			impressoraAllColumns,
			impressoraPrimaryKeyColumns,
		)
	}

	value := reflect.Indirect(reflect.ValueOf(o))
	typ := reflect.TypeOf(o).Elem()
	n := typ.NumField()

	updateMap := M{}
	for _, col := range fields {
		for i := 0; i < n; i++ {
			f := typ.Field(i)
			if f.Tag.Get("boil") == col {
				updateMap[col] = value.Field(i).Interface()
			}
		}
	}

	slice := ImpressoraSlice{o}
	if rowsAff, err := slice.UpdateAll(ctx, tx, updateMap); err != nil {
		t.Error(err)
	} else if rowsAff != 1 {
		t.Error("wanted one record updated but got", rowsAff)
	}
}

func testImpressorasUpsert(t *testing.T) {
	t.Parallel()

	if len(impressoraAllColumns) == len(impressoraPrimaryKeyColumns) {
		t.Skip("Skipping table with only primary key columns")
	}
	if len(mySQLImpressoraUniqueColumns) == 0 {
		t.Skip("Skipping table with no unique columns to conflict on")
	}

	seed := randomize.NewSeed()
	var err error
	// Attempt the INSERT side of an UPSERT
	o := Impressora{}
	if err = randomize.Struct(seed, &o, impressoraDBTypes, false); err != nil {
		t.Errorf("Unable to randomize Impressora struct: %s", err)
	}

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()
	if err = o.Upsert(ctx, tx, boil.Infer(), boil.Infer()); err != nil {
		t.Errorf("Unable to upsert Impressora: %s", err)
	}

	count, err := Impressoras().Count(ctx, tx)
	if err != nil {
		t.Error(err)
	}
	if count != 1 {
		t.Error("want one record, got:", count)
	}

	// Attempt the UPDATE side of an UPSERT
	if err = randomize.Struct(seed, &o, impressoraDBTypes, false, impressoraPrimaryKeyColumns...); err != nil {
		t.Errorf("Unable to randomize Impressora struct: %s", err)
	}

	if err = o.Upsert(ctx, tx, boil.Infer(), boil.Infer()); err != nil {
		t.Errorf("Unable to upsert Impressora: %s", err)
	}

	count, err = Impressoras().Count(ctx, tx)
	if err != nil {
		t.Error(err)
	}
	if count != 1 {
		t.Error("want one record, got:", count)
	}
}
